/**
 * The mark for a metric id, if it has one.
 *
 * kromgo's version badges are named <product>_version, which is the only thing
 * that reliably says which product a tile is about.
 */
export function logoFor(metric: string): Poly[] | undefined {
  const m = /^([a-z0-9]+)_version$/.exec(metric);
  return m ? LOGO_POLYS[m[1]!] : undefined;
}
